{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "overview_card",
        "features_title",
        "core_tech_card",
        "battery_card",
        "attachments_card",
        "quick_actions_title",
        "learn_more_button",
        "sources_title",
        "dyson_website_button"
      ]
    },
    "overview_card": {
      "type": "Card",
      "props": {},
      "children": [
        "overview_header_stack",
        "overview_description"
      ]
    },
    "overview_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "overview_icon",
        "overview_title"
      ]
    },
    "overview_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/house.svg"
      },
      "children": []
    },
    "overview_title": {
      "type": "Text",
      "props": {
        "text": "Dyson V15 Detect Absolute Overview",
        "variant": "h2"
      },
      "children": []
    },
    "overview_description": {
      "type": "Text",
      "props": {
        "text": "The Dyson V15 Detect Absolute is a powerful cordless vacuum cleaner designed for comprehensive whole-home cleaning. It features advanced technology to detect microscopic dust, measure it, and display the proof on an LCD screen, ensuring a deep and thorough clean."
      },
      "children": []
    },
    "features_title": {
      "type": "Text",
      "props": {
        "text": "Key Features and Specifications",
        "variant": "h2"
      },
      "children": []
    },
    "core_tech_card": {
      "type": "Card",
      "props": {},
      "children": [
        "core_tech_heading",
        "core_tech_list_stack"
      ]
    },
    "core_tech_heading": {
      "type": "Text",
      "props": {
        "text": "Core Technologies",
        "variant": "h3"
      },
      "children": []
    },
    "core_tech_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "laser_detect_item",
        "piezo_sensor_item",
        "lcd_screen_item",
        "dyson_motor_item",
        "root_cyclone_item"
      ]
    },
    "laser_detect_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "laser_detect_name",
        "laser_detect_desc"
      ]
    },
    "laser_detect_name": {
      "type": "Text",
      "props": {
        "text": "Laser Detect Technology",
        "variant": "label"
      },
      "children": []
    },
    "laser_detect_desc": {
      "type": "Text",
      "props": {
        "text": "A precisely angled laser illuminates invisible dust on hard floors, making it visible for thorough cleaning."
      },
      "children": []
    },
    "piezo_sensor_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "piezo_sensor_name",
        "piezo_sensor_desc"
      ]
    },
    "piezo_sensor_name": {
      "type": "Text",
      "props": {
        "text": "Piezo Sensor",
        "variant": "label"
      },
      "children": []
    },
    "piezo_sensor_desc": {
      "type": "Text",
      "props": {
        "text": "Acoustically senses dust particles, automatically increasing suction power when higher concentrations are detected."
      },
      "children": []
    },
    "lcd_screen_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "lcd_screen_name",
        "lcd_screen_desc"
      ]
    },
    "lcd_screen_name": {
      "type": "Text",
      "props": {
        "text": "LCD Screen",
        "variant": "label"
      },
      "children": []
    },
    "lcd_screen_desc": {
      "type": "Text",
      "props": {
        "text": "Displays the size and number of dust particles, along with real-time performance information like run time and power mode."
      },
      "children": []
    },
    "dyson_motor_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "dyson_motor_name",
        "dyson_motor_desc"
      ]
    },
    "dyson_motor_name": {
      "type": "Text",
      "props": {
        "text": "Dyson Hyperdymium™ Motor",
        "variant": "label"
      },
      "children": []
    },
    "dyson_motor_desc": {
      "type": "Text",
      "props": {
        "text": "Generates powerful suction for deep cleaning carpets and hard floors."
      },
      "children": []
    },
    "root_cyclone_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "root_cyclone_name",
        "root_cyclone_desc"
      ]
    },
    "root_cyclone_name": {
      "type": "Text",
      "props": {
        "text": "Root Cyclone™ Technology",
        "variant": "label"
      },
      "children": []
    },
    "root_cyclone_desc": {
      "type": "Text",
      "props": {
        "text": "14 cyclones generate forces of up to 100,000g to capture dust and debris without loss of suction."
      },
      "children": []
    },
    "battery_card": {
      "type": "Card",
      "props": {},
      "children": [
        "battery_heading",
        "battery_runtime_text",
        "battery_description"
      ]
    },
    "battery_heading": {
      "type": "Text",
      "props": {
        "text": "Battery Run Time",
        "variant": "h3"
      },
      "children": []
    },
    "battery_runtime_text": {
      "type": "Text",
      "props": {
        "text": "Up to 60 minutes",
        "variant": "label"
      },
      "children": []
    },
    "battery_description": {
      "type": "Text",
      "props": {
        "text": "Offers powerful fade-free suction across all floor types in Eco mode. Actual run time varies based on power mode, floor type, and attachments used."
      },
      "children": []
    },
    "attachments_card": {
      "type": "Card",
      "props": {},
      "children": [
        "attachments_heading",
        "attachments_list_stack"
      ]
    },
    "attachments_heading": {
      "type": "Text",
      "props": {
        "text": "Main Attachments",
        "variant": "h3"
      },
      "children": []
    },
    "attachments_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "digital_motorbar_item",
        "fluffy_optic_item",
        "hair_screw_item",
        "crevice_tool_item",
        "combination_tool_item",
        "wand_clip_item",
        "docking_station_item"
      ]
    },
    "digital_motorbar_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "digital_motorbar_name",
        "digital_motorbar_desc"
      ]
    },
    "digital_motorbar_name": {
      "type": "Text",
      "props": {
        "text": "Digital Motorbar™ Cleaner Head",
        "variant": "label"
      },
      "children": []
    },
    "digital_motorbar_desc": {
      "type": "Text",
      "props": {
        "text": "Automatically de-tangles hair from the brush bar as you clean."
      },
      "children": []
    },
    "fluffy_optic_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "fluffy_optic_name",
        "fluffy_optic_desc"
      ]
    },
    "fluffy_optic_name": {
      "type": "Text",
      "props": {
        "text": "Fluffy Optic™ Cleaner Head",
        "variant": "label"
      },
      "children": []
    },
    "fluffy_optic_desc": {
      "type": "Text",
      "props": {
        "text": "Illuminates microscopic dust on hard floors."
      },
      "children": []
    },
    "hair_screw_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "hair_screw_name",
        "hair_screw_desc"
      ]
    },
    "hair_screw_name": {
      "type": "Text",
      "props": {
        "text": "Hair Screw Tool",
        "variant": "label"
      },
      "children": []
    },
    "hair_screw_desc": {
      "type": "Text",
      "props": {
        "text": "Anti-tangle conical brush bar for hair and pet hair."
      },
      "children": []
    },
    "crevice_tool_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "crevice_tool_name",
        "crevice_tool_desc"
      ]
    },
    "crevice_tool_name": {
      "type": "Text",
      "props": {
        "text": "Crevice Tool",
        "variant": "label"
      },
      "children": []
    },
    "crevice_tool_desc": {
      "type": "Text",
      "props": {
        "text": "For cleaning in tight gaps and narrow spaces."
      },
      "children": []
    },
    "combination_tool_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "combination_tool_name",
        "combination_tool_desc"
      ]
    },
    "combination_tool_name": {
      "type": "Text",
      "props": {
        "text": "Combination Tool",
        "variant": "label"
      },
      "children": []
    },
    "combination_tool_desc": {
      "type": "Text",
      "props": {
        "text": "Two tools in one – wide nozzle and brush, for quick switching between cleaning and dusting tasks."
      },
      "children": []
    },
    "wand_clip_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "wand_clip_name",
        "wand_clip_desc"
      ]
    },
    "wand_clip_name": {
      "type": "Text",
      "props": {
        "text": "Wand Clip",
        "variant": "label"
      },
      "children": []
    },
    "wand_clip_desc": {
      "type": "Text",
      "props": {
        "text": "Stores the combination and crevice tool on the vacuum's wand."
      },
      "children": []
    },
    "docking_station_item": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "docking_station_name",
        "docking_station_desc"
      ]
    },
    "docking_station_name": {
      "type": "Text",
      "props": {
        "text": "Docking Station",
        "variant": "label"
      },
      "children": []
    },
    "docking_station_desc": {
      "type": "Text",
      "props": {
        "text": "Wall-mounted charging and storage for the vacuum and accessories."
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "learn_more_button": {
      "type": "Button",
      "props": {
        "label": "Learn More About Dyson V15 Detect Absolute"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.dyson.com/vacuums/cordless-vacuums/v15-detect/absolute"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "dyson_website_button": {
      "type": "Button",
      "props": {
        "label": "Dyson Official Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.dyson.com"
          }
        }
      },
      "children": []
    }
  }
}
